async () => {
const inp=document.querySelector('vaadin-text-field, vaadin-text-field input'); 
const tf=document.querySelector('vaadin-text-field'); tf.value=''; tf.dispatchEvent(new Event('change'));tf.dispatchEvent(new CustomEvent('value-changed',{detail:{value:''}}));
await new Promise(r=>setTimeout(r,1500));
const g=document.querySelector('vaadin-grid'); const seen=new Map();
for(let i=0;i<80;i++){
 g._getRenderedRows().forEach(r=>{const c=[...r.querySelectorAll('vaadin-grid-cell-content, td')].map(x=>x.textContent.trim()); const t=[...r.children].map(td=>td.firstElementChild? td.firstElementChild.assignedNodes?.()[0]?.textContent:'' );});
 g._getRenderedRows().forEach(r=>{const d=r._item; if(d) seen.set(d.id??JSON.stringify(d),d);});
 g.scrollToIndex(i*20); await new Promise(r=>setTimeout(r,250));
}
const items=[...seen.values()];
return {n:items.length, c:items.filter(d=>d.company?.name?.startsWith('Linens')&&d.status?.name==='Imported lead').length, sample:items[0]};
}

