async () => {
await new Promise(r=>setTimeout(r,1500));
const g=document.querySelector('vaadin-grid'); const seen=new Map();
const rd=()=>[...g.shadowRoot.querySelectorAll('tbody tr')].forEach(tr=>{const c=[...tr.querySelectorAll('td')].map(td=>td.querySelector('slot')?.assignedNodes()[0]?.textContent?.trim()); if(c[2]) seen.set(c[2],c);});
for(let i=0;i<200;i+=5){ g.scrollToIndex(i); await new Promise(r=>setTimeout(r,300)); rd(); }
const items=[...seen.values()];
return {n:items.length, c:items.filter(c=>c[4].startsWith('Linens')&&c[3]==='Imported lead').map(c=>c[2])};
}

